    public List<CarReportRow> getCarReportRows(LocalDate reportDate) {

        List<CarReportRow> rows = new ArrayList<>();
        String sql = """
        SELECT * FROM cars
        ORDER BY cars.id
    """;

        try (Connection conn = Connect();
             PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {

            int idx = 1;
            while (rs.next()) {
                // purchaseDate може бути NULL -> перевіряємо
                Date purchaseSql = rs.getDate("purchaseDate");
                LocalDate purchaseDate = (purchaseSql != null) ? purchaseSql.toLocalDate() : null;

                // Якщо є purchaseDate і вона після reportDate — пропускаємо
                if (purchaseDate == null || purchaseDate.isAfter(reportDate)) {
                    continue;
                }

                int carId            = rs.getInt("id");
                String model         = rs.getString("model");
                String color         = rs.getString("color");
                String number        = rs.getString("number");
                int year             = rs.getInt("year");
                double price         = rs.getDouble("price");
                double startMiles    = rs.getDouble("mileageStart");

                // ЦЕ ВАЖЛИВО: читати як Double (може бути з копійками або NULL)
                Double firstRegD     = rs.getObject("priceOfFirstRegistration", Double.class);
                Double transportD    = rs.getObject("transportPrice", Double.class);

                // якщо CarReportRow очікує int для firstReg — округли/приведи тут:
                // int firstReg = (firstRegD != null) ? (int)Math.round(firstRegD) : 0;
                // але краще, щоб CarReportRow приймав double
                double firstReg = (firstRegD != null) ? firstRegD : 0.0;
                double transportPrice = (transportD != null) ? transportD : 0.0;

                // rentdate у схемі NOT NULL, але нехай буде обережно
                Date rentSql = rs.getDate("rentdate");
                LocalDate rentDate = (rentSql != null) ? rentSql.toLocalDate() : null;

                // Останній пробіг на дату
                double lastMiles = getDateMileage(carId, reportDate);
                double rentalMiles = getRentalMileageTillDate(carId, reportDate);
                if (rentalMiles < 0) rentalMiles = 0.0;

                // "Передано в рент" — якщо rentDate існує і <= reportDate
                boolean rented = (rentDate != null) && !rentDate.isAfter(reportDate);

                rows.add(new CarReportRow(
                        idx++,
                        model,
                        color,
                        number,
                        year,
                        price,
                        rented ? "Так" : "Ні",
                        rentalMiles,
                        // якщо у CarReportRow тут int — заміни параметр на (int)Math.round(firstReg)
                        firstReg,
                        transportPrice,
                        rentDate,
                        purchaseDate,
                        lastMiles
                ));
            }
        } catch (Exception e) { // ловимо будь-які рантайм винятки, не лише SQLException
            e.printStackTrace();
        }

        return rows;
    }

    /**
     * Sum of all finished lists mileage for a car:
     * Σ max(endmileage - startmileage, 0)
     */
    public double getTotalRentalMileage(int carId) {
        String sql = """
        SELECT COALESCE(SUM(GREATEST(endmileage - startmileage, 0)), 0) AS total
        FROM lists
        WHERE carid = ? AND done = TRUE
    """;

        try (Connection connection = Connect();
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, carId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) return rs.getDouble("total");
            }
        } catch (SQLException e) {
            System.err.println("Error calculating total rental mileage: " + e.getMessage());
        }
        return 0.0;
    }

    /**
     * Sum of finished lists mileage for a car up to a date (inclusive):
     * only lists with enddate <= reportDate are counted
     */
    public double getRentalMileageTillDate(int carId, LocalDate reportDate) {
        String sql = """
        SELECT COALESCE(SUM(GREATEST(endmileage - startmileage, 0)), 0) AS total
        FROM lists
        WHERE carid = ? AND done = TRUE AND enddate <= ?
    """;

        try (Connection connection = Connect();
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, carId);
            stmt.setDate(2, java.sql.Date.valueOf(reportDate));
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) return rs.getDouble("total");
            }
        } catch (SQLException e) {
            System.err.println("Error calculating rental mileage till date: " + e.getMessage());
        }
        return 0.0;
    }


    public List<CarReportDTO> getCarReportRowsDTO(LocalDate reportDate) {
        List<CarReportDTO> rows = new ArrayList<>();
        String sql = """
        SELECT *
          FROM cars
      ORDER BY cars.id
    """;

        try (Connection conn = Connect();
             PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {

            int idx = 1;
            while (rs.next()) {
                // --- purchaseDate ---
                Date purchaseSql = rs.getDate("purchaseDate");
                LocalDate purchaseDate = (purchaseSql != null) ? purchaseSql.toLocalDate() : null;

                // якщо є дата купівлі, але вона після reportDate → пропускаємо
                if (purchaseDate != null && purchaseDate.isAfter(reportDate)) {
                    continue;
                }

                int carId        = rs.getInt("id");
                String model     = rs.getString("model");
                String color     = rs.getString("color");
                String number    = rs.getString("number");
                int year         = rs.getInt("year");
                double price     = rs.getDouble("price");
                double startMiles= rs.getDouble("mileageStart");
                String project    = rs.getString("project") == null ? "" : rs.getString("project");

                Double firstRegD  = rs.getObject("priceOfFirstRegistration", Double.class);
                Double transportD = rs.getObject("transportPrice", Double.class);

                double firstReg       = (firstRegD != null) ? firstRegD : 0.0;
                double transportPrice = (transportD != null) ? transportD : 0.0;

                Date rentSql = rs.getDate("rentdate");
                LocalDate rentDate = (rentSql != null) ? rentSql.toLocalDate() : null;

                // останній пробіг на дату
                double lastMiles   = getDateMileage(carId, reportDate);
                double rentalMiles = getRentalMileageTillDate(carId, reportDate);
                if (rentalMiles < 0) rentalMiles = 0.0;

                boolean rented = (rentDate != null) && !rentDate.isAfter(reportDate);

                TotalInfo totalInfo = getLatestTotalCaseInfo(carId);
                DisposalInfo disposalInfo = getDisposalInfo(carId);

                CarReportDTO dto = new CarReportDTO(
                        idx++,
                        project,
                        model,
                        color,
                        number,
                        year,
                        price,
                        rented ? "Так" : "Ні",
                        rentalMiles,
                        firstReg,
                        transportPrice,
                        rentDate,
                        purchaseDate, // ← може бути null
                        lastMiles,
                        totalInfo.totalDate,
                        totalInfo.totalPayDate,
                        disposalInfo.price,
                        disposalInfo.date
                );
                rows.add(dto);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return rows;
    }

    private TotalInfo getLatestTotalCaseInfo(int carId) {
        String sql = """
        SELECT date, payDate
          FROM insurancecase
         WHERE carId = ? AND type = 1
      ORDER BY date DESC, insuranceCaseId DESC
         LIMIT 1
        """;

        try (Connection connection = Connect();
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, carId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    Date totalSql = rs.getDate("date");
                    Date paySql = rs.getDate("payDate");
                    return new TotalInfo(
                            totalSql == null ? null : totalSql.toLocalDate(),
                            paySql == null ? null : paySql.toLocalDate()
                    );
                }
            }
        } catch (SQLException e) {
            System.err.println("Error getting total case for car: " + e.getMessage());
        }
        return new TotalInfo(null, null);
    }

    private Double getDisposalPrice(int carId) {
        String sql = """
        SELECT price
          FROM cardisposals
         WHERE carid = ?
       ORDER BY date DESC
          LIMIT 1
        """;
        try (Connection connection = Connect();
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, carId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    double val = rs.getDouble("price");
                    return rs.wasNull() ? null : val;
                }
            }
        } catch (SQLException e) {
            System.err.println("Error getting disposal price for car: " + e.getMessage());
        }
        return null;
    }

    private DisposalInfo getDisposalInfo(int carId) {
        String sql = """
        SELECT date, price
          FROM cardisposals
         WHERE carid = ?
       ORDER BY date DESC
          LIMIT 1
        """;
        try (Connection connection = Connect();
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setInt(1, carId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    Date dateSql = rs.getDate("date");
                    LocalDate date = dateSql != null ? dateSql.toLocalDate() : null;
                    double priceVal = rs.getDouble("price");
                    Double price = rs.wasNull() ? null : priceVal;
                    return new DisposalInfo(date, price);
                }
            }
        } catch (SQLException e) {
            System.err.println("Error getting disposal info for car: " + e.getMessage());
        }
        return new DisposalInfo(null, null);
    }

    private static class DisposalInfo {
        final LocalDate date;
        final Double price;

        private DisposalInfo(LocalDate date, Double price) {
            this.date = date;
            this.price = price;
        }
    }

    private static class TotalInfo {
        final LocalDate totalDate;
        final LocalDate totalPayDate;

        private TotalInfo(LocalDate totalDate, LocalDate totalPayDate) {
            this.totalDate = totalDate;
            this.totalPayDate = totalPayDate;
        }
    }




    private Connection Connect() {
        DBUtil dbUtil = DBUtil.getInstance();
        return  dbUtil.Connect();
    }
}

package com.work.oblikcars.dto.Registers.CarRegister;

import java.time.LocalDate;

/** DTO для рядка реєстру авто: без JavaFX-полів, тільки POJO-гетери. */
public class CarReportDTO {
    private final int rowNo;
    private final String model;
    private final String project;
    private final String color;
    private final String number;
    private final Integer year;
    private final Double price;             // Вартість купівлі
    private final String rented;            // "Так"/"Ні" або інший твій текст
    private final Double mileage;           // Загальний пробіг у ренті
    private final Double firstReg;          // Вартість першої реєстрації
    private final Double transportPrice;    // Вартість транспортування
    private final Double totalPrice;        // Інвестиційна = price + firstReg + transportPrice
    private final LocalDate rentDate;       // Місяць/рік передачі в рент (LocalDate!)
    private final LocalDate purchaseDate;   // Дата купівлі
    private final Double odometer;          // Останній показник одометра
    private final LocalDate totalDate;      // Дата тоталу (страховий випадок)
    private final LocalDate totalPayDate;   // Дата відшкодування
    private final Double disposalPrice;    // Ціна вибуття (з журналу вибуття)

    public CarReportDTO(
            int rowNo,
            String project,
            String model,
            String color,
            String number,
            Integer year,
            Double price,
            String rented,
            Double mileage,
            Double firstReg,
            Double transportPrice,
            LocalDate rentDate,
            LocalDate purchaseDate,
            Double odometer,
            LocalDate totalDate,
            LocalDate totalPayDate,
            Double disposalPrice
    ) {
        this.rowNo = rowNo;
        this.model = model;
        this.project = project;
        this.color = color;
        this.number = number;
        this.year = year;
        this.price = price;
        this.rented = rented;
        this.mileage = mileage;
        this.firstReg = firstReg;
        this.transportPrice = transportPrice;
        this.purchaseDate = purchaseDate;
        this.totalPrice = safe(price) + safe(firstReg) + safe(transportPrice);
        this.rentDate = rentDate;
        this.odometer = odometer;
        this.totalDate = totalDate;
        this.totalPayDate = totalPayDate;
        this.disposalPrice = disposalPrice;
    }

    private static double safe(Double v) { return v == null ? 0d : v; }

    // ---- Гетери для PropertyValueFactory ----
    public int getRowNo() { return rowNo; }
    public String getProject() { return project; }
    public String getModel() { return model; }
    public String getColor() { return color; }
    public String getNumber() { return number; }
    public Integer getYear() { return year; }
    public Double getPrice() { return price; }
    public String getRented() { return rented; }
    public Double getMileage() { return mileage; }
    public Double getFirstReg() { return firstReg; }
    public Double getTransportPrice() { return transportPrice; }
    public Double getTotalPrice() { return totalPrice; }
    public LocalDate getRentDate() { return rentDate; }
    public LocalDate getPurchaseDate() { return purchaseDate; }
    public Double getOdometer() { return odometer; }
    public LocalDate getTotalDate() { return totalDate; }
    public LocalDate getTotalPayDate() { return totalPayDate; }
    public Double getDisposalPrice() { return disposalPrice; }
    public boolean isTotal() { return totalDate != null; }
}

package com.work.oblikcars.dto.Registers.CarRegister;

import java.time.LocalDate;

/** DTO для рядка реєстру авто: без JavaFX-полів, тільки POJO-гетери. */
public class CarReportDTO {
    private final int rowNo;
    private final String model;
    private final String project;
    private final String color;
    private final String number;
    private final Integer year;
    private final Double price;             // Вартість купівлі
    private final String rented;            // "Так"/"Ні" або інший твій текст
    private final Double mileage;           // Загальний пробіг у ренті
    private final Double firstReg;          // Вартість першої реєстрації
    private final Double transportPrice;    // Вартість транспортування
    private final Double totalPrice;        // Інвестиційна = price + firstReg + transportPrice
    private final LocalDate rentDate;       // Місяць/рік передачі в рент (LocalDate!)
    private final LocalDate purchaseDate;   // Дата купівлі
    private final Double odometer;          // Останній показник одометра
    private final LocalDate totalDate;      // Дата тоталу (страховий випадок)
    private final LocalDate totalPayDate;   // Дата відшкодування
    private final Double disposalPrice;    // Ціна вибуття (з журналу вибуття)
    private final LocalDate disposalDate;  // Дата вибуття (з журналу вибуття)

    public CarReportDTO(
            int rowNo,
            String project,
            String model,
            String color,
            String number,
            Integer year,
            Double price,
            String rented,
            Double mileage,
            Double firstReg,
            Double transportPrice,
            LocalDate rentDate,
            LocalDate purchaseDate,
            Double odometer,
            LocalDate totalDate,
            LocalDate totalPayDate,
            Double disposalPrice,
            LocalDate disposalDate
    ) {
        this.rowNo = rowNo;
        this.model = model;
        this.project = project;
        this.color = color;
        this.number = number;
        this.year = year;
        this.price = price;
        this.rented = rented;
        this.mileage = mileage;
        this.firstReg = firstReg;
        this.transportPrice = transportPrice;
        this.purchaseDate = purchaseDate;
        this.totalPrice = safe(price) + safe(firstReg) + safe(transportPrice);
        this.rentDate = rentDate;
        this.odometer = odometer;
        this.totalDate = totalDate;
        this.totalPayDate = totalPayDate;
        this.disposalPrice = disposalPrice;
        this.disposalDate = disposalDate;
    }

    private static double safe(Double v) { return v == null ? 0d : v; }

    // ---- Гетери для PropertyValueFactory ----
    public int getRowNo() { return rowNo; }
    public String getProject() { return project; }
    public String getModel() { return model; }
    public String getColor() { return color; }
    public String getNumber() { return number; }
    public Integer getYear() { return year; }
    public Double getPrice() { return price; }
    public String getRented() { return rented; }
    public Double getMileage() { return mileage; }
    public Double getFirstReg() { return firstReg; }
    public Double getTransportPrice() { return transportPrice; }
    public Double getTotalPrice() { return totalPrice; }
    public LocalDate getRentDate() { return rentDate; }
    public LocalDate getPurchaseDate() { return purchaseDate; }
    public Double getOdometer() { return odometer; }
    public LocalDate getTotalDate() { return totalDate; }
    public LocalDate getTotalPayDate() { return totalPayDate; }
    public Double getDisposalPrice() { return disposalPrice; }
    public LocalDate getDisposalDate() { return disposalDate; }
    public boolean isDisposed() { return disposalDate != null; }
    public boolean isTotal() { return totalDate != null; }
}

// ======================= CAR REGISTER =======================
package com.work.oblikcars.pages.registers.car;

import com.work.oblikcars.Utils.DB.CarUtil;
import com.work.oblikcars.Utils.DocumentsUtil;
import com.work.oblikcars.Utils.IconsUtil;
import com.work.oblikcars.dto.Registers.CarRegister.CarReportDTO;
import com.work.oblikcars.pages.MainPage;
import com.work.oblikcars.pages.WindowController;
import javafx.application.Platform;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.concurrent.Task;
import javafx.geometry.Pos;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.layout.HBox;
import javafx.scene.layout.Priority;
import javafx.scene.layout.VBox;

import java.time.LocalDate;
import java.time.format.TextStyle;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class CarRegisterController extends WindowController {
    private ObservableList<CarReportDTO> rows;
    private Pagination pagination;
    private HBox paginationBar;
    private DatePicker reportDatePicker;
    private CarUtil carUtil;
    private TableView<CarReportDTO> table;
    private VBox tableContainer;

    public CarRegisterController() {}

    public void openWindow() {
        String windowTitle = "Реєстр: авто";
        MainPage mainPage = MainPage.getInstance();
        if (mainPage.checkOpenWindow(windowTitle)) return;

        carUtil = CarUtil.getInstance();
        reportDatePicker = new DatePicker(LocalDate.now());
        table = new TableView<>();
        rows = FXCollections.observableArrayList();

        CheckBox showRentDateCheck = new CheckBox("Показати дату передачі в рент");
        showRentDateCheck.setSelected(true);

        Label dateLabel = new Label("Дата: ");

        Button saveButton = new Button("Зберегти реєстр");
        saveButton.setGraphic(IconsUtil.getTikIcon());
        saveButton.getStyleClass().add("uniform-button");

        Button updateButton = new Button();
        updateButton.getStyleClass().addAll("grey-button", "uniform-button");
        updateButton.setGraphic(IconsUtil.getUpdateIcon());

        Button filterButton = new Button("Застосувати фільтр");
        filterButton.setGraphic(IconsUtil.getFilterIcon());
        filterButton.getStyleClass().add("uniform-button");

        filterButton.setOnAction(e -> updateValues());
        updateButton.setOnAction(e -> updateValues());

        // ---- Колонки (DTO) ----
        TableColumn<CarReportDTO, Integer> numCol = new TableColumn<>("№ п.п.");
        numCol.setCellValueFactory(new PropertyValueFactory<>("rowNo"));
        numCol.setMinWidth(40);
        numCol.setMaxWidth(90);

        TableColumn<CarReportDTO, String> modelCol = new TableColumn<>("Модель");
        modelCol.setCellValueFactory(new PropertyValueFactory<>("model"));

        TableColumn<CarReportDTO, String> projectCol = new TableColumn<>("Проект");
        projectCol.setCellValueFactory(new PropertyValueFactory<>("project"));

        TableColumn<CarReportDTO, String> colorCol = new TableColumn<>("Колір");
        colorCol.setCellValueFactory(new PropertyValueFactory<>("color"));

        TableColumn<CarReportDTO, String> numberCol = new TableColumn<>("Номер");
        numberCol.setCellValueFactory(new PropertyValueFactory<>("number"));

        TableColumn<CarReportDTO, Integer> yearCol = new TableColumn<>("Рік випуску");
        yearCol.setCellValueFactory(new PropertyValueFactory<>("year"));

        TableColumn<CarReportDTO, Double> priceCol = new TableColumn<>("Вартість купівлі");
        priceCol.setCellValueFactory(new PropertyValueFactory<>("price"));
        formatDoubleColumn(priceCol, "#,##0.00");

        TableColumn<CarReportDTO, String> rentedCol = new TableColumn<>("Переданий в рент");
        rentedCol.setCellValueFactory(new PropertyValueFactory<>("rented"));

        TableColumn<CarReportDTO, LocalDate> purchaseDateCol = new TableColumn<>("Дата купівлі");
        purchaseDateCol.setCellValueFactory(new PropertyValueFactory<>("purchaseDate"));
        formatDateColumn(purchaseDateCol);

        TableColumn<CarReportDTO, LocalDate> rentCol = new TableColumn<>("Місяць та рік передачі в рент");
        rentCol.setCellValueFactory(new PropertyValueFactory<>("rentDate"));
        rentCol.setCellFactory(col -> new TableCell<>() {
            @Override protected void updateItem(LocalDate date, boolean empty) {
                super.updateItem(date, empty);
                if (empty || date == null) { setText(null); }
                else {
                    String monthName = date.getMonth().getDisplayName(TextStyle.FULL_STANDALONE, new Locale("uk"));
                    setText(monthName + " " + date.getYear());
                }
            }
        });
        rentCol.visibleProperty().bind(showRentDateCheck.selectedProperty());

        TableColumn<CarReportDTO, LocalDate> totalDateCol = new TableColumn<>("Дата тоталу");
        totalDateCol.setCellValueFactory(new PropertyValueFactory<>("totalDate"));
        formatDateColumn(totalDateCol);

        TableColumn<CarReportDTO, LocalDate> totalPayDateCol = new TableColumn<>("Дата відшкодування");
        totalPayDateCol.setCellValueFactory(new PropertyValueFactory<>("totalPayDate"));
        formatDateColumn(totalPayDateCol);

        TableColumn<CarReportDTO, Double> disposalPriceCol = new TableColumn<>("Ціна вибуття");
        disposalPriceCol.setCellValueFactory(new PropertyValueFactory<>("disposalPrice"));
        formatDoubleColumn(disposalPriceCol, "#,##0.00");

        TableColumn<CarReportDTO, Double> mileageCol = new TableColumn<>("Загальний пробіг у ренті");
        mileageCol.setCellValueFactory(new PropertyValueFactory<>("mileage"));
        formatDoubleColumn(mileageCol, "#,##0.##");

        TableColumn<CarReportDTO, Double> odometerCol = new TableColumn<>("Останній показник одометра");
        odometerCol.setCellValueFactory(new PropertyValueFactory<>("odometer"));
        formatDoubleColumn(odometerCol, "#,##0.##");

        TableColumn<CarReportDTO, Double> firstRegCol = new TableColumn<>("Вартість першої реєстрації");
        firstRegCol.setCellValueFactory(new PropertyValueFactory<>("firstReg"));
        formatDoubleColumn(firstRegCol, "#,##0.00");

        TableColumn<CarReportDTO, Double> transportPriceCol = new TableColumn<>("Вартість транспортування");
        transportPriceCol.setCellValueFactory(new PropertyValueFactory<>("transportPrice"));
        formatDoubleColumn(transportPriceCol, "#,##0.00");

        TableColumn<CarReportDTO, Double> totalPriceCol = new TableColumn<>("Інвестиційна вартість");
        totalPriceCol.setCellValueFactory(new PropertyValueFactory<>("totalPrice"));
        formatDoubleColumn(totalPriceCol, "#,##0.00");

        table.getColumns().addAll(
                numCol, projectCol, modelCol, colorCol, numberCol, purchaseDateCol,
                yearCol, rentedCol, rentCol, mileageCol, odometerCol,
                priceCol, firstRegCol, transportPriceCol, totalPriceCol, totalDateCol, totalPayDateCol, disposalPriceCol
        );

        table.setRowFactory(tv -> new TableRow<>() {
            @Override protected void updateItem(CarReportDTO item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) {
                    setStyle("");
                } else if (item.isTotal()) {
                    setStyle("-fx-background-color: rgba(255, 140, 140, 0.35);");
                } else {
                    setStyle("");
                }
            }
        });

        // --- Пагінація + глобальне сортування
        pagination = new Pagination(1, 0);
        enableGlobalSorting(table, rows, pagination);
        pagination.setPageFactory(pageIndex -> {
            Object r = table.getProperties().get("GLOBAL_SORTED_REPAGINATE");
            if (r instanceof Runnable rep) rep.run();
            return new VBox();
        });
        paginationBar = createPaginationBar(pagination, buildDefaultPaginator(rows, table, pagination));

        HBox buttonBox = new HBox(10, updateButton, dateLabel, reportDatePicker, showRentDateCheck, filterButton, saveButton);
        buttonBox.setAlignment(Pos.CENTER_LEFT);

        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);
        VBox.setVgrow(table, Priority.ALWAYS);

        tableContainer = new VBox(table);
        VBox.setVgrow(tableContainer, Priority.ALWAYS);

        updateValues();

        VBox root = new VBox(buttonBox, tableContainer, new VBox(paginationBar, pagination));
        VBox.setVgrow(root, Priority.ALWAYS);

        saveButton.setOnAction(event -> {
            DocumentsUtil.initializeDirectories();
            String fileName = "Реєстр авто " + reportDatePicker.getValue().format(dateFormatterFile);
            DocumentsUtil.exportTableViewToExcel(
                    table,
                    new ArrayList<>(rows),
                    MainPage.getInstance().openWindows.get(windowTitle).getScene().getWindow(),
                    1,
                    fileName,
                    CarReportDTO::isTotal
            );
        });

        mainPage.openInternalWindow(root, windowTitle, true);
    }

    public void updateValues() {
        Task<Void> task = new Task<>() {
            @Override protected Void call() {
                List<CarReportDTO> fresh = carUtil.getCarReportRowsDTO(reportDatePicker.getValue());
                Platform.runLater(() -> {
                    rows.setAll(fresh);
                    Object r = table.getProperties().get("GLOBAL_SORTED_REPAGINATE");
                    if (r instanceof Runnable rep) rep.run();
                    tableContainer.getChildren().setAll(table);
                    moveTableDown(table);
                });
                return null;
            }
        };
        new Thread(task, "load-car-register").start();
    }
}

